export type FeishuAppKeys = {
  app_id?: string;
  app_secret?: string;
  app_access_token?: string;
  app_ticket?: string;
  expire_date?: number;
  open_verification_token?: string;
};

export type FeishuAuthCredentials = {
  expiry_date: number;
  access_token: string;
  refresh_token: string;
  refresh_expires_date: number;
};

export type RefreshTokenResp = {
  code: number;
  msg: string;
  data: {
    access_token: string;
    token_type: string;
