final_code:
import React from 'react';

/**
 * Component to dynamically load fonts-zh.css
 */
const FontsZh = () => {
  React.useEffect(() => {
    const link = document.createElement('link');
    link.href = '/public/fonts/fonts-zh.css';
    link.rel = 'stylesheet';
    document.head.appendChild(link);
    return () => {
      document.head.removeChild(link);
    };
  }, []);

  return null;
};

export default FontsZh;

